  assert len(impls)==36 and set(impls)=={'RlKernelAttentionImpl'},impls
  if attn is None:
   return {'rank':self.rank,'variant':variant,'native':True,'source_root':os.environ['CAUSAL_SOURCE_ROOT'],'attention_impls':impls,'readback':integration.readback()}
  logp=integration._rl_kernel_operators['logp']
