  native=self._source_native
  if variant=='dynamic_transport' and 'source-main-' in os.environ['CAUSAL_SOURCE_ROOT']:
   src=textwrap.dedent(inspect.getsource(native))
   tree=ast.parse(src);fn=tree.body[0]
   for node in ast.walk(fn):
    if isinstance(node,ast.If) and any(isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='replay_cap' for t in n.targets) for n in node.body):
     node.body=ast.parse('finite_counts = torch.isfinite(processed_logits).sum(dim=-1)\nnum_logprobs = int(finite_counts.max().item())').body
   scope=dict(native.__globals__);exec('from __future__ import annotations\n'+ast.unparse(tree),scope);native=scope[fn.name]
  logp._native_forward=native
